from builtins import object
import time
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.oam.btssm.btssm_factory import BtssmFactory

logger = BackgroundLogger.Instance()


class CellOperations(object):
    """
    Cell Operations
    """
    def __init__(self):
        self.oam_tool = BtssmFactory().get_instance().oam_tool

    def verify_bts_status(self, **kwargs):
        """
        Function to verify bts status
        """
        logger.info("implementation Not available for BTSSM")

    def block_cell(self, **kwargs):
        """
        Function to block cell
        """
        cellid = kwargs.get("cellid")
        priority = kwargs.get("priority", "normal")
        id_type = kwargs.get("id_type", "global")
        timeout = kwargs.get("timeout", "5min")
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["cellid", "priority", "id_type", "timeout"]}
        self.oam_tool.block_cell(cellid=cellid, priority=priority, id_type=id_type,
                                 timeout=timeout, **kwargs)

    def unblock_cell(self, **kwargs):
        """
        Function to unblock cell
        """
        cellid = kwargs.get("cellid")
        priority = kwargs.get("priority", "normal")
        id_type = kwargs.get("id_type", "global")
        timeout = kwargs.get("timeout", "5min")
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["cellid", "priority", "id_type", "timeout"]}
        self.oam_tool.unblock_cell(cellid=cellid, priority=priority, id_type=id_type,
                                   timeout=timeout, **kwargs)
